<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/bootstrap.php';msp2RequireAccess();if(($_SERVER['REQUEST_METHOD']??'GET')!=='POST')msp2Redirect('cobranza/configuracion_gestion.php');
try{$conn->beginTransaction();$actualizar=function(string $tabla,string $idCampo,array $filas,array $campos)use($conn):void{foreach($filas as $id=>$row){if(!ctype_digit((string)$id)||!is_array($row))continue;$sets=[];$params=[':id'=>(int)$id];foreach($campos as $campo=>$max){$valor=$campo==='activo'?(isset($row[$campo])?1:0):($campo==='orden'?(int)($row[$campo]??100):trim((string)($row[$campo]??'')));if(is_int($max)&&$max>0&&mb_strlen((string)$valor)>$max)throw new RuntimeException('Un texto supera el máximo permitido.');if($campo!=='activo'&&$campo!=='orden'&&$valor==='')throw new RuntimeException('Los nombres y textos no pueden quedar vacíos.');$sets[]=$campo.'=:'.$campo;$params[':'.$campo]=$valor;}$stmt=$conn->prepare('UPDATE dbo.'.$tabla.' SET '.implode(',',$sets).' WHERE '.$idCampo.'=:id');$stmt->execute($params);}};$actualizar('msp_cobranza_tipos_gestion','id_tipo_gestion',(array)($_POST['tipos']??[]),['nombre'=>80,'orden'=>0,'activo'=>0]);$actualizar('msp_cobranza_resultados_gestion','id_resultado_gestion',(array)($_POST['resultados']??[]),['nombre'=>100,'orden'=>0,'activo'=>0]);$actualizar('msp_cobranza_plantillas_aviso','id_plantilla_aviso',(array)($_POST['plantillas']??[]),['nombre'=>100,'asunto'=>200,'cuerpo'=>10000,'orden'=>0,'activo'=>0]);$conn->commit();msp2SetFlash('success','Configuración de cobranza actualizada.');}catch(Throwable $e){if($conn->inTransaction())$conn->rollBack();msp2SetFlash($e instanceof RuntimeException?'warning':'danger',$e instanceof RuntimeException?$e->getMessage():'No fue posible guardar la configuración.');}msp2Redirect('cobranza/configuracion_gestion.php');
